sp_widget.client_script:
api.controller = function($sce, $timeout) {
    var c = this;
    var copyFeedbackTimeout = null;
    c.linkCopied = false;

    c.trustedContent = $sce.trustAsHtml(c.data.announcement ? c.data.announcement.content || '' : '');

    c.primaryActions = [];
    c.secondaryActions = [];
    c.tertiaryActions = [];

    var actions = c.data.announcement && c.data.announcement.actions ? c.data.announcement.actions : [];

    actions.forEach(function(action) {
        switch (action.level) {
            case 'primary':
                c.primaryActions.push(action);
                break;

            case 'secondary':
                c.secondaryActions.push(action);
                break;

            case 'tertiary':
                c.tertiaryActions.push(action);
                break;
        }
    });

    c.toggleSaved = function() {
        var announcement = c.data.announcement;

        if (!announcement || !announcement.tracking || announcement._saving) {
            return;
        }

        var shouldSave = !announcement.tracking.saved;
        announcement._saving = true;

        c.server.get({
            action: 'toggle_saved',
            communication_id: announcement.sys_id,
            saved: shouldSave

        }).then(function(response) {
            if (response.data.success) {
                announcement.tracking.saved = response.data.saved;
            }

        }).finally(function() {
            announcement._saving = false;
        });
    };

    function showCopied() {
        if (copyFeedbackTimeout) {
            $timeout.cancel(copyFeedbackTimeout);
        }

        $timeout(function() {
            c.linkCopied = true;

            copyFeedbackTimeout = $timeout(function() {
                c.linkCopied = false;
                copyFeedbackTimeout = null;
            }, 2000);
        });
    }

    c.copyLink = function() {
        var announcement = c.data.announcement;

        if (!announcement)
            return;

        var url = window.location.origin + window.location.pathname + '?id=aes_details&announcement=' + encodeURIComponent(announcement.sys_id);

        navigator.clipboard.writeText(url).then(function() {
            showCopied();

        })
    };

    c.backToAnnouncements = function() {
        window.location.href = window.location.pathname + '?id=aes_announcements';
    };

};

sp_widget.css:
.aes-announcement-detail {
    max-width: 1120px;
    margin: 0 auto;
    padding: $aes-space-2xl $aes-page-gutter;
}


/* ============================================================
   TOP BAR
   ============================================================ */

.aes-announcement-detail__topbar {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: $aes-space-lg;
    margin-bottom: $aes-space-lg;
}

.aes-announcement-detail__tools {
    display: flex;
    align-items: center;
    gap: $aes-space-sm;
}

.aes-announcement-detail__back,
.aes-announcement-detail__tool,
.aes-announcement-detail__more {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: $aes-space-sm;

    border: 0;
    background: transparent;

    color: $link-color;
    font-size: $font-size-small;
    font-weight: 600;

    cursor: pointer;
    transition:
        color $aes-transition-fast,
        background $aes-transition-fast;
}

.aes-announcement-detail__back:hover,
.aes-announcement-detail__tool:hover {
    color: $link-hover-color;
}

.aes-announcement-detail__tool[disabled] {
    opacity: $aes-opacity-disabled;
    cursor: default;
}

.aes-announcement-detail__tool[aria-pressed="true"] {
    color: $aes-saved-color;
}

.aes-announcement-detail__more {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    color: $text-primary;
}

.aes-announcement-detail__more:hover {
    background: $background-tertiary;
}

/* ============================================================
   ARTICLE
   ============================================================ */

.aes-announcement-detail__article {
    overflow: hidden;

    background: $background-primary;
    border: 1px solid $border-tertiary;
    border-radius: $aes-radius-lg;
    box-shadow: $aes-shadow-lg;
}


/* ============================================================
   HEADER
   ============================================================ */

.aes-announcement-detail__header {
    padding:
        $aes-space-2xl
        $aes-space-2xl
        $aes-space-xl;
}

.aes-announcement-detail__badges {
    display: flex;
    align-items: center;
    flex-wrap: wrap;
    gap: $aes-space-sm;

    margin-bottom: $aes-space-lg;
}

.aes-announcement-detail__badge,
.aes-announcement-detail__category {
    display: inline-flex;
    align-items: center;

    padding: $aes-space-xs $aes-space-sm;

    border-radius: 999px;

    font-size: $font-size-xs;
    font-weight: 600;
    line-height: 1.2;
}

.aes-announcement-detail__badge--new {
    background: $aes-new-background;
    color: $aes-new-color;
}

.aes-announcement-detail__badge--urgent {
    background: $aes-urgent-background;
    color: $aes-urgent-color;
}

.aes-announcement-detail__category {
    background: $brand-primary-lightest;
    color: $aes-deep-forest;
}


/* ============================================================
   TITLE
   ============================================================ */

.aes-announcement-detail__title {
    max-width: 850px;

    margin: 0 0 $aes-space-sm;

    color: $text-primary;

    font-family: $headings-font-family;
    font-size: $font-size-h1;
    font-weight: $headings-font-weight;
    line-height: $headings-line-height;
}

.aes-announcement-detail__description {
    max-width: 850px;

    margin: 0 0 $aes-space-lg;

    color: $text-secondary;

    font-size: $font-size-large;
    line-height: $line-height-base;
}


/* ============================================================
   DATES
   ============================================================ */

.aes-announcement-detail__dates {
    display: flex;
    align-items: center;
    flex-wrap: wrap;
    gap: $aes-space-sm;

    color: $text-tertiary;

    font-size: $font-size-small;
}

.aes-announcement-detail__date {
    display: inline-flex;
    align-items: center;
    gap: $aes-space-xs;
}

.aes-announcement-detail__date-separator {
    color: $border-secondary;
}


/* ============================================================
   HERO IMAGE
   ============================================================ */

.aes-announcement-detail__media {
    max-width: 850px;
    margin:
        $aes-space-lg
        auto
        0;

    overflow: hidden;
    background: $background-secondary;
    border-radius: $aes-radius-md;
}

.aes-announcement-detail__image {
    display: block;
    width: 100%;
    height: 300px;
    object-fit: contain;
}

/* ============================================================
   RICH CONTENT
   ============================================================ */

.aes-announcement-detail__content {
    max-width: 850px;

    margin: 0 auto;
    padding:
        $aes-space-xl
        0;

    color: $text-primary;

    font-size: $font-size-base;
    line-height: 1.7;
}

.aes-announcement-detail__content p:last-child {
    margin-bottom: 0;
}

.aes-announcement-detail__content img {
    max-width: 100%;
    height: auto;
}


/* ============================================================
   ACTIONS
   ============================================================ */

.aes-announcement-detail__actions {
    max-width: 850px;

    margin: 0 auto;
    padding:
        $aes-space-xl
        $aes-space-xl;

    border-top: 1px solid $border-tertiary;
}

.aes-announcement-detail__primary-actions {
    display: flex;
    flex-wrap: wrap;
    gap: $aes-space-sm;
}

.aes-announcement-detail__action {
    font-weight: $btn-font-weight;
    cursor: pointer;

    transition:
        background $aes-transition-fast,
        color $aes-transition-fast,
        border-color $aes-transition-fast;
}


/* Primary */

.aes-announcement-detail__action--primary {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: $aes-space-sm;

    min-height: 44px;

    padding:
        $aes-space-sm
        $aes-space-xl;

    border: 1px solid $btn-primary-border;
    border-radius: $aes-radius-md;

    background: $btn-primary-bg;
    color: $btn-primary-color;
}

.aes-announcement-detail__action--primary:hover {
    background: $aes-deep-forest;
    border-color: $aes-deep-forest;
}


/* Secondary */

.aes-announcement-detail__secondary-actions {
    display: flex;
    align-items: center;
    flex-wrap: wrap;
    gap: $aes-space-lg;

    margin-top: $aes-space-lg;
}

.aes-announcement-detail__action--secondary {
    padding: 0;

    border: 0;
    background: transparent;

    color: $link-color;
}

.aes-announcement-detail__action--secondary:hover {
    color: $link-hover-color;
    text-decoration: underline;
}


/* ============================================================
   FOOTER
   ============================================================ */

.aes-announcement-detail__footer {
    display: flex;
    align-items: center;
    flex-wrap: wrap;
    gap: $aes-space-sm;

    margin:
        $aes-space-lg
        $aes-space-2xl
        0;

    padding:
        $aes-space-lg
        0
        $aes-space-xl;

    border-top: 1px solid $border-tertiary;

    color: $text-tertiary;

    font-size: $font-size-xs;
}


/* ============================================================
   UNAVAILABLE
   ============================================================ */

.aes-announcement-detail__unavailable {
    max-width: 720px;

    margin: $aes-space-3xl auto;
    padding: $aes-space-2xl;

    text-align: center;

    background: $background-primary;
    border: 1px solid $border-tertiary;
    border-radius: $aes-radius-lg;
}


/* ============================================================
   MOBILE
   ============================================================ */

@media (max-width: 767px) {

    .aes-announcement-detail {
        padding:
            $aes-space-lg
            $aes-space-md;
    }

    .aes-announcement-detail__topbar {
        align-items: center;
    }

    .aes-announcement-detail__tool span {
        display: none;
    }

    .aes-announcement-detail__header {
        padding: $aes-space-xl $aes-space-lg;
    }

    .aes-announcement-detail__title {
        font-size: $font-size-h2;
    }

    .aes-announcement-detail__description {
        font-size: $font-size-base;
    }

        
  .aes-announcement-detail__media {    
    margin: $aes-space-lg $aes-space-lg 0;
    }

    .aes-announcement-detail__image {
        height: auto;
        max-height: 280px;
    }
  
    .aes-announcement-detail__actions {
        padding: $aes-space-xl $aes-space-lg;
    }
  
     .aes-announcement-detail__content {
        padding: $aes-space-xl $aes-space-lg;
    }

    .aes-announcement-detail__action--primary {
        width: 100%;
    }

    .aes-announcement-detail__footer {
        margin: $aes-space-md $aes-space-lg 0;
    }
}

sp_widget.script:
(function() {

    data.announcement = null;
    data.error = '';

    var announcementId = $sp.getParameter('announcement');

    if (!announcementId) {
        data.error = 'missing_announcement';
        return;
    }

    var portal = $sp.getPortalRecord();

    if (!portal) {
        data.error = 'portal_not_found';
        return;
    }

    var channelResolver = new AESPortalChannelResolver();
    var channelId = channelResolver.getChannel(portal.getUniqueValue());

    if (!channelId) {
        data.error = 'channel_not_found';
        return;
    }

    var displayTypes = getDisplayTypes();

    if (!displayTypes.length) {
        data.error = 'display_types_not_configured';
        return;
    }

    if (input && input.action === 'toggle_saved') {
        var tracking = new AESCommunicationTracking();
        var result;

        if (input.saved) {
            result = tracking.save(input.communication_id);
        } else {
            result = tracking.unsave(input.communication_id);
        }

        data.success = result.success;
        data.reason = result.reason || '';
        data.saved = result.success ? !!input.saved : null;

        return;
    }

    var service = new AESAnnouncementService();

    data.announcement =
        service.getById(
            announcementId, {
                channel: channelId,
                displayTypes: displayTypes
            }
        );

    if (!data.announcement) {
        data.error = 'announcement_not_available';
    }


    function getDisplayTypes() {
        var value = options.display_types;

        var result = [];
        var values = value.split(',');

        for (var i = 0; i < values.length; i++) {
            var displayType = values[i].trim();

            if (displayType)
                result.push(displayType);
        }

        return result;
    }

})();
